1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/dmi_poll.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	#include "hybrid/v_regfile_xfer.hpp"
12	
13	#include <algorithm>
14	#include <array>
15	#include <cstdint>
16	#include <span>
17	
18	namespace hybrid
19	{
20	
21	class StateDrain
22	{
23	public:
24	  using RD = ResumeDriver;
25	
26	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
27	  // the mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the
28	  // unset sentinel; only the V dump sweep consults it, and it throws there if
29	  // a V drain is reached with the GPA unset (no silent dump to a bogus
30	  // address). The simulator passes the real value from platform.main_memory.
31	  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset)
32	      : bus_{bus}, scratch_gpa_{scratch_gpa}
33	  {}
34	
35	  // F16: stash the warmup-window snapshot (mcycle, minstret captured K
36	  // retires after vsim entry). Both drain() and drain_with_passthrough()
37	  // copy these into the returned state. Zero when MeasureStartSnapshot
38	  // never fired (K=0 or workload exited inside the warmup window).
39	  void set_warmup_snapshot(uint64_t mcycle, uint64_t minstret)
40	  {
41	    warmup_mcycle_   = mcycle;
42	    warmup_minstret_ = minstret;
43	  }
44	
45	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
46	  // drain_with_passthrough when the QEMU 1 snapshot is available.
47	  auto drain() -> hybrid_state_v1
48	  {
49	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
50	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
51	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
52	                   "StateDrain halt");
53	
54	    hybrid_state_v1 state{};
55	    state.magic   = HYBRID_STATE_MAGIC;
56	    state.version = HYBRID_STATE_VERSION;
57	    state.flags   = HYBRID_FLAG_RV64;
58	    // L6: dcsr.prv holds the privilege the hart was in when the halt landed.
59	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
60	                                  "StateDrain DCSR") & 0x3u;
61	
62	    for (uint16_t i = 1; i < 32; ++i)
63	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
64	
65	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
66	    state.mcycle_at_measure_start   = warmup_mcycle_;
67	    state.minstret_at_measure_start = warmup_minstret_;
68	    return state;
69	  }
70	
71	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
72	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
73	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
74	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
75	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
76	  // and vreg remain pass-through (read-only / too large for DM).
77	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
78	  // contribution would otherwise be discarded as the passthrough preserves
79	  // QEMU1's pre-handoff value.
80	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
81	  {
82	    auto state       = input;
83	    const auto fresh = drain();
84	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
85	              std::begin(state.gpr) + 1);
86	    state.pc   = fresh.pc;
87	    state.priv = fresh.priv;  // L6: privilege at the exit halt, not QEMU1's
88	
89	    if (input.flags & HYBRID_FLAG_FP) {
90	      for (uint16_t i = 0; i < 32; ++i)
91	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
92	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
93	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
94	    }
95	
96	    if (input.flags & HYBRID_FLAG_V) {
97	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
98	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
99	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
100	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
101	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
102	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
103	    }
104	
105	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
106	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
107	    // dropped and the stale QEMU1 value passes through into the drained state.
108	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
109	
110	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
111	    // restores them), so re-read them -- an in-ROI write must reach the drained
112	    // state instead of the stale QEMU1 passthrough value.
113	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
114	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
115	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
116	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
117	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
118	
119	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
120	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
121	
122	    // V data regfile: dump v0..v31 to the shared scratch region via the
123	    // Program Buffer LAST -- after every architectural read above -- so the
124	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
125	    // cannot corrupt the values already captured. The simulator's
126	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
127	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
128	    if (input.flags & HYBRID_FLAG_V)
129	      dump_v_to_scratch(input.vlenb);
130	
131	    state.mcycle_at_measure_start   = warmup_mcycle_;
132	    state.minstret_at_measure_start = warmup_minstret_;
133	    return state;
134	  }
135	
136	  // cosim_roi F1: checkpoint drain. Same capture as drain_with_passthrough,
137	  // but the hart must keep running afterwards. The exit drain may clobber
138	  // freely (the run ends there); a checkpoint must undo the dump sweep's
139	  // clobbers -- vtype/vl/vstart and the x5/x6/x7 scratch -- from the freshly
140	  // drained values, then resume. DPC is untouched, so the hart continues
141	  // exactly where the halt landed.
142	  auto drain_checkpoint(const hybrid_state_v1& input) -> hybrid_state_v1
143	  {
144	    const auto state = drain_with_passthrough(input);
145	
146	    if (input.flags & HYBRID_FLAG_V)
147	      undo_v_sweep_clobbers(state);
148	
149	    bus_.write(RD::kDmcontrol,
150	               RD::kDmcontrolDmactive | RD::kDmcontrolResumereq);
151	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllresumeack,
152	                   "StateDrain checkpoint resume");
153	    return state;
154	  }
155	
156	  // cosim_redesign F1: full drain with NO QEMU1 passthrough input -- every
157	  // populated field comes from the hart. Flags are probed from misa, vlenb
158	  // from its CSR, and the trap CSR block + PMP are read via (tolerant)
159	  // Abstract Commands. Non-destructive: the V dump sweep's clobbers are
160	  // undone and a force-enabled FS/VS is restored, so the hart can continue
161	  // (lock-step record loop). The hart is left HALTED -- the caller decides
162	  // between step, resume, or exit.
163	  auto drain_full() -> hybrid_state_v1
164	  {
165	    auto state = drain();  // halt + GPRs/pc/priv, flags = RV64
166	
167	    const uint64_t misa =
168	      read_register_64(bus_, regno_csr(RD::kCsrMisa), "StateDrain misa");
169	    if (misa & (kMisaF | kMisaD)) state.flags |= HYBRID_FLAG_FP;
170	    if (misa & kMisaV) state.flags |= HYBRID_FLAG_V;
171	
172	    state.mstatus  = read_register_64(bus_, regno_csr(RD::kCsrMstatus));
173	    state.mepc     = read_register_64(bus_, regno_csr(RD::kCsrMepc));
174	    state.mtvec    = read_register_64(bus_, regno_csr(RD::kCsrMtvec));
175	    state.mcause   = read_register_64(bus_, regno_csr(RD::kCsrMcause));
176	    state.mtval    = read_register_64(bus_, regno_csr(RD::kCsrMtval));
177	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
178	    state.medeleg  = read_register_64(bus_, regno_csr(RD::kCsrMedeleg));
179	    state.mideleg  = read_register_64(bus_, regno_csr(RD::kCsrMideleg));
180	    state.mip      = read_register_64(bus_, regno_csr(RD::kCsrMip));
181	    state.mie      = read_register_64(bus_, regno_csr(RD::kCsrMie));
182	    state.satp     = read_register_64(bus_, regno_csr(RD::kCsrSatp));
183	
184	    // PMP: read_register_64 maps a missing entry to 0 (tolerant), matching
185	    // the resume side's tolerant writes. Odd pmpcfg CSRs do not exist on
186	    // RV64 and stay zero.
187	    for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
188	      state.pmpaddr[i] =
189	        read_register_64(bus_, regno_csr(RD::kCsrPmpaddr0 + i));
190	    for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
191	      state.pmpcfg[i] =
192	        read_register_64(bus_, regno_csr(RD::kCsrPmpcfg0 + i));
193	
194	    // FS/VS at Off NACKs the FPR / V accesses below. Force the minimal
195	    // enable for the reads, restore the architectural mstatus afterwards;
196	    // the record keeps the original value either way.
197	    uint64_t live_mstatus = state.mstatus;
198	    if ((state.flags & HYBRID_FLAG_FP)
199	        && (live_mstatus & RD::kMstatusFsMask) == 0)
200	      live_mstatus |= RD::kMstatusFsInitial;
201	    if ((state.flags & HYBRID_FLAG_V)
202	        && (live_mstatus & RD::kMstatusVsMask) == 0)
203	      live_mstatus |= RD::kMstatusVsInitial;
204	    const bool mstatus_forced = live_mstatus != state.mstatus;
205	    if (mstatus_forced) write_csr_tolerant(RD::kCsrMstatus, live_mstatus);
206	
207	    if (state.flags & HYBRID_FLAG_FP) {
208	      for (uint16_t i = 0; i < 32; ++i)
209	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
210	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
211	    }
212	
213	    if (state.flags & HYBRID_FLAG_V) {
214	      state.vlenb  = read_register_64(bus_, regno_csr(RD::kCsrVlenb));
215	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
216	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
217	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
218	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
219	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
220	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
221	    }
222	
223	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
224	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
225	
226	    // V data dump LAST (same reasoning as drain_with_passthrough), then undo
227	    // the sweep's clobbers so the hart can keep executing.
228	    if (state.flags & HYBRID_FLAG_V) {
229	      dump_v_to_scratch(state.vlenb);
230	      undo_v_sweep_clobbers(state);
231	    }
232	
233	    if (mstatus_forced) write_csr_tolerant(RD::kCsrMstatus, state.mstatus);
234	    return state;
235	  }
